// https://stackoverflow.com/a/62969380 + fix to remove empty entries (.filter(entry => entry))
// also maps nested objects e.g. {q: {since: 123}} will become ?q[since]=123
function buildQueryString(query) {
    const build = (obj, prefix) => {
        return Object.entries(obj).flatMap(([key, value]) => {
            const paramKey = prefix ? `${prefix}[${key}]` : key;
            if (value && typeof value === "object" && !Array.isArray(value)) {
                return build(value, paramKey);
            }
            return value !== undefined && value !== null
                ? `${paramKey}=${value}`
                : [];
        });
    };
    return build(query).join("&");
}

class AlbyResponseError extends Error {
    constructor(status, statusText, headers, 
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    error) {
        let message = status.toString();
        if (statusText) {
            message += ` ${statusText}`;
        }
        message += ": ";
        if (error.message) {
            message += error.message;
        }
        else {
            message += JSON.stringify(error);
        }
        super(message);
        this.status = status;
        this.statusText = statusText;
        this.headers = headers;
        this.error = error;
    }
}

const BASE_URL = "https://api.getalby.com";
async function fetchWithRetries(url, init, max_retries = 0) {
    const res = await fetch(url, init);
    if (res.status === 429 && max_retries > 0) {
        const rateLimitReset = Number(res.headers.get("x-rate-limit-reset"));
        const rateLimitRemaining = Number(res.headers.get("x-rate-limit-remaining"));
        const timeTillReset = rateLimitReset * 1000 - Date.now();
        let timeToWait = 1000;
        if (rateLimitRemaining === 0)
            timeToWait = timeTillReset;
        await new Promise((resolve) => setTimeout(resolve, timeToWait));
        return fetchWithRetries(url, init, max_retries - 1);
    }
    return res;
}
async function request({ auth, endpoint, params: query = {}, request_body, method, max_retries, base_url = BASE_URL, user_agent, headers, ...options }) {
    const url = new URL(base_url + endpoint);
    url.search = buildQueryString(query);
    const isPost = method === "POST" && !!request_body;
    const authHeader = auth
        ? await auth.getAuthHeader(url.href, method)
        : undefined;
    const response = await fetchWithRetries(url.toString(), {
        headers: {
            ...(isPost
                ? { "Content-Type": "application/json; charset=utf-8" }
                : undefined),
            ...authHeader,
            ...headers,
            ...{
                "User-Agent": user_agent ?? "@getalby/sdk",
                "X-User-Agent": user_agent ?? "@getalby/sdk",
            },
        },
        method,
        body: isPost ? JSON.stringify(request_body) : undefined,
        ...options,
    }, max_retries);
    if (!response.ok) {
        const error = await response.json();
        throw new AlbyResponseError(response.status, response.statusText, response.headers, error);
    }
    return response;
}
// eslint-disable-next-line @typescript-eslint/no-explicit-any
async function rest(args) {
    const response = await request(args);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return response.json();
}

